(3459686, 481080, 75289, '<td valign="top">Ooh, sultry. Shame about the burnt-out sun. Nice though :)</td>', 'Ooh, sultry. Shame about the burnt-out sun. Nice though :)', '2007-03-14 09:53:21.000000', NULL, 1),
(3459695, 483889, 75289, '<td valign="top">Great way to shoot a fence</td>', 'Great way to shoot a fence', '2007-03-14 09:54:33.000000', NULL, 1),
(3459702, 482009, 66201, '<td valign="top">I think that this is a fantastic image, but it''s just so small - I have set the page to full size, but your sizing makes this a tiny image compared to others - then your border is so big - I would have loved to have seen the image fill this border and then have the same border put on to it so that it was really POW! You''re competing with 400 other images to grab the viewer''s attention - you''ve gotta make them want to stay and look a while longer. I love the lines leading out to the left - lovely mood and contrasts.</td>', 'I think that this is a fantastic image, but it''s just so small - I have set the page to full size, but your sizing makes this a tiny image compared to others - then your border is so big - I would have loved to have seen the image fill this border and then have the same border put on to it so that it was really POW! You''re competing with 400 other images to grab the viewer''s attention - you''ve gotta make them want to stay and look a while longer. I love the lines leading out to the left - lovely mood and contrasts.', '2007-03-14 09:55:05.000000', NULL, 1),
(3459724, 483518, 66201, '<td valign="top">I think your border is heavy and metallic/aluminium-looking: just detracts too much from the image which in itself is lovely and gentle. Love the partial desat.</td>', 'I think your border is heavy and metallic/aluminium-looking: just detracts too much from the image which in itself is lovely and gentle. Love the partial desat.', '2007-03-14 09:58:14.000000', NULL, 1),
(3459730, 481080, 52572, '<td valign="top">awesome angle and perspective shot.</td>', 'awesome angle and perspective shot.', '2007-03-14 09:59:15.000000', NULL, 1),
