(3461490, 482900, 65234, '<td valign="top">The color of his face looks unnaturally orange on my monitor, and the dark hair and eyebrows and lack of wrinkles kind of contradict the title.</td>', 'The color of his face looks unnaturally orange on my monitor, and the dark hair and eyebrows and lack of wrinkles kind of contradict the title.', '2007-03-14 16:23:26.000000', NULL, 1),
(3461497, 483662, 65234, '<td valign="top">Nice composition.  The shading in the background makes the negative space much more interesting.</td>', 'Nice composition.  The shading in the background makes the negative space much more interesting.', '2007-03-14 16:25:06.000000', NULL, 1),
(3461498, 480990, 68751, '<td valign="top">almost looks like it was drawn by pencils, very good work!</td>', 'almost looks like it was drawn by pencils, very good work!', '2007-03-14 16:25:09.000000', NULL, 1),
(3461499, 481149, 65234, '<td valign="top">Background is awfully busy and keeps distracting me from an interesting face.</td>', 'Background is awfully busy and keeps distracting me from an interesting face.', '2007-03-14 16:26:01.000000', NULL, 1),
(3461502, 483742, 68751, '<td valign="top">Beautiful lighting from behind!</td>', 'Beautiful lighting from behind!', '2007-03-14 16:27:03.000000', NULL, 1),
(3461507, 483387, 65234, '<td valign="top">Nice architecture for this challenge, and the viewpoint is far enough away that the clothing isn''t dating it one way or another ... it''s more timeless-looking from this distance.</td>', 'Nice architecture for this challenge, and the viewpoint is far enough away that the clothing isn''t dating it one way or another ... it''s more timeless-looking from this distance.', '2007-03-14 16:27:58.000000', NULL, 1),
(3461514, 482286, 68751, '<td valign="top">LOVE the title! 8!</td>', 'LOVE the title! 8!', '2007-03-14 16:29:08.000000', NULL, 1),
(3461516, 481723, 65234, '<td valign="top">Looks like the kind of thing that got banned from modern playgrounds as too dangerous.  And looks like fun :-)</td>', 'Looks like the kind of thing that got banned from modern playgrounds as too dangerous.  And looks like fun :-)', '2007-03-14 16:29:14.000000', NULL, 1),
(3461521, 483398, 65234, '<td valign="top">Grain works nicely on this subject.  Border is distracting where the white disappears into the picture.</td>', 'Grain works nicely on this subject.  Border is distracting where the white disappears into the picture.', '2007-03-14 16:30:21.000000', NULL, 1),
(3461522, 482040, 65234, '<td valign="top">I think I would have preferred a crop that gave the statue more headroom.</td>', 'I think I would have preferred a crop that gave the statue more headroom.', '2007-03-14 16:31:16.000000', NULL, 1),
(3461527, 481878, 75103, '<td valign="top">probably a wider frame would have worked better</td>', 'probably a wider frame would have worked better', '2007-03-14 16:32:39.000000', NULL, 1),
(3461535, 482624, 65234, '<td valign="top">An old cemetery is a perfect subject for this challenge, and I like this perspective.</td>', 'An old cemetery is a perfect subject for this challenge, and I like this perspective.', '2007-03-14 16:34:03.000000', NULL, 1),
(3461538, 483677, 65234, '<td valign="top">Love the one slightly narrowed eye; looks mildly quizzical.</td>', 'Love the one slightly narrowed eye; looks mildly quizzical.', '2007-03-14 16:34:50.000000', NULL, 1),
(3461548, 481813, 65234, '<td valign="top">Yes, it does.  I wish I had the $$$ to buy and restore something like this!  Good choice for this challenge.</td>', 'Yes, it does.  I wish I had the $$$ to buy and restore something like this!  Good choice for this challenge.', '2007-03-14 16:36:23.000000', NULL, 1),
(3461551, 482609, 65234, '<td valign="top">Gritty in multiple meanings of the word.</td>', 'Gritty in multiple meanings of the word.', '2007-03-14 16:36:51.000000', NULL, 1),
