(3461569, 483124, 65234, '<td valign="top">I didn''t think cormorants quacked, but then I haven''t researched it.  Looks more overexposed than grainy on my monitor.</td>', 'I didn''t think cormorants quacked, but then I haven''t researched it.  Looks more overexposed than grainy on my monitor.', '2007-03-14 16:40:59.000000', NULL, 1),
(3461572, 483809, 65234, '<td valign="top">Nice subject for this.</td>', 'Nice subject for this.', '2007-03-14 16:42:28.000000', NULL, 1),
