(3461577, 483965, 65234, '<td valign="top">The lowkey lighting and the grain work very well with this subject.</td>', 'The lowkey lighting and the grain work very well with this subject.', '2007-03-14 16:45:49.000000', NULL, 1),
(3461578, 480683, 69333, '<td valign="top">Interesting</td>', 'Interesting', '2007-03-14 16:46:09.000000', NULL, 1),
