(3461582, 481272, 65234, '<td valign="top">The sky and the building have the same stony texture, which bothers me visually.</td>', 'The sky and the building have the same stony texture, which bothers me visually.', '2007-03-14 16:48:15.000000', NULL, 1),
(3461583, 483570, 65234, '<td valign="top">Cute, old-fashioned scene.</td>', 'Cute, old-fashioned scene.', '2007-03-14 16:48:39.000000', NULL, 1),
(3461585, 483829, 65234, '<td valign="top">Great idea with the lighting and grain and well-loved stuffed animal combining to make this quite spooky!</td>', 'Great idea with the lighting and grain and well-loved stuffed animal combining to make this quite spooky!', '2007-03-14 16:50:04.000000', NULL, 1),
(3461587, 483811, 65234, '<td valign="top">The dark sky and the shadow make this really intriguing.</td>', 'The dark sky and the shadow make this really intriguing.', '2007-03-14 16:51:11.000000', NULL, 1),
(3461595, 483562, 65234, '<td valign="top">Nicely composed and the sepia and grain work well together.</td>', 'Nicely composed and the sepia and grain work well together.', '2007-03-14 16:52:37.000000', NULL, 1),
(3461598, 481180, 65234, '<td valign="top">Snow works very well for this challenge; perspective is a bit too centered for my taste.</td>', 'Snow works very well for this challenge; perspective is a bit too centered for my taste.', '2007-03-14 16:53:52.000000', NULL, 1),
(3461600, 483179, 65234, '<td valign="top">Very dramatic clouds ... I think they''re clouds.  And I like the irony of the intact gate when all the windows are missing.  Makes for an interesting image.</td>', 'Very dramatic clouds ... I think they''re clouds.  And I like the irony of the intact gate when all the windows are missing.  Makes for an interesting image.', '2007-03-14 16:55:33.000000', NULL, 1),
(3461607, 481518, 65234, '<td valign="top">Like the tones with the grain.</td>', 'Like the tones with the grain.', '2007-03-14 16:56:49.000000', NULL, 1),
(3461611, 482221, 65234, '<td valign="top">Looks like an interesting place.</td>', 'Looks like an interesting place.', '2007-03-14 16:59:07.000000', NULL, 1),
(3461626, 483908, 65234, '<td valign="top">Looks like a painting.  Love the path leading to the gazebo and the big tree on the left balancing that side.  Actually, now that I scroll around a bit, I like it a lot more with the sky, the top of the tree and the top of the gazebo cropped out.  That gives the path about 2/3 of the image and the gazebo about 1/3, and in this case I really like following that rule :-)</td>', 'Looks like a painting.  Love the path leading to the gazebo and the big tree on the left balancing that side.  Actually, now that I scroll around a bit, I like it a lot more with the sky, the top of the tree and the top of the gazebo cropped out.  That gives the path about 2/3 of the image and the gazebo about 1/3, and in this case I really like following that rule :-)', '2007-03-14 17:05:10.000000', NULL, 1),
(3461627, 483930, 29011, '<td valign="top">The added noise/grain really works for this shot, but would''ve like to see the grain in monochrome here, not in color.</td>', 'The added noise/grain really works for this shot, but would''ve like to see the grain in monochrome here, not in color.', '2007-03-14 17:05:16.000000', NULL, 1),
(3461650, 480626, 42100, '<td valign="top">My initial thought was that it would be nice to see some hint of his eye.  But I think that thought may be wrong, as it might change the emotive feel of this.  I love how you found the perfect balance of detail and grain.  Well done!</td>', 'My initial thought was that it would be nice to see some hint of his eye.  But I think that thought may be wrong, as it might change the emotive feel of this.  I love how you found the perfect balance of detail and grain.  Well done!', '2007-03-14 17:15:19.000000', NULL, 1),
(3461656, 480626, 61651, '<td valign="top">The textures are palpable in this image, with good background blur and lighting.  A very striking photo.</td>', 'The textures are palpable in this image, with good background blur and lighting.  A very striking photo.', '2007-03-14 17:16:54.000000', NULL, 1),
(3461661, 483310, 27087, '<td valign="top">Think I would like the original better since it is so interesting. Anyhow 8</td>', 'Think I would like the original better since it is so interesting. Anyhow 8', '2007-03-14 17:18:23.000000', NULL, 1),
(3461677, 483821, 42100, '<td valign="top">Very painterly...I can''t help thinking...sort of a cross between a Doolittle and a Rockwell.  Very nice, I like this!</td>', 'Very painterly...I can''t help thinking...sort of a cross between a Doolittle and a Rockwell.  Very nice, I like this!', '2007-03-14 17:22:45.000000', NULL, 1),
(3461685, 483809, 51269, '<td valign="top">A wonderful image of what we see in Vermont all the time &amp; don''t appreciate ! Great composition and the grain is perfect for this image &amp; the challenge, great job.</td>', 'A wonderful image of what we see in Vermont all the time & don''t appreciate ! Great composition and the grain is perfect for this image & the challenge, great job.', '2007-03-14 17:26:48.000000', NULL, 1),
