INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3461819, 482198, 23484, '<td valign="top">Absolutely amazing shot. I don''t know what else to say. 10</td>', 'Absolutely amazing shot. I don''t know what else to say. 10', '2007-03-14 18:32:35.000000', NULL, 1),
(3461825, 483770, 23484, '<td valign="top">This is a great shot. Should have used $100 bill though. 8</td>', 'This is a great shot. Should have used $100 bill though. 8', '2007-03-14 18:34:17.000000', NULL, 1),
(3461832, 483262, 23484, '<td valign="top">Nice job. I like the colors. I think the grain give a neat perspective to the buildings.</td>', 'Nice job. I like the colors. I think the grain give a neat perspective to the buildings.', '2007-03-14 18:36:20.000000', NULL, 1),
(3461836, 482268, 14414, '<td valign="top">I can''t decide on this one - the grain <i>works</i> fine; but not sure if it adds anything...<br/>grain +low saturation is nice though.</td>', 'I can''t decide on this one - the grain works fine; but not sure if it adds anything...grain +low saturation is nice though.', '2007-03-14 18:37:12.000000', NULL, 1),
(3461837, 483864, 67152, '<td valign="top">nice use of grain on this classic car image - could have been taken years ago with real film.</td>', 'nice use of grain on this classic car image - could have been taken years ago with real film.', '2007-03-14 18:37:59.000000', NULL, 1),
(3461839, 483600, 67152, '<td valign="top">I really like the light on this one</td>', 'I really like the light on this one', '2007-03-14 18:38:37.000000', NULL, 1),
(3461851, 483507, 67152, '<td valign="top">Thisis a great vista and great colors - but I am afraid I don''t like this subject with the grain.  This looks like it would be a wonderful image if the grain were not there (I know this is a grain challenge...)</td>', 'Thisis a great vista and great colors - but I am afraid I don''t like this subject with the grain.  This looks like it would be a wonderful image if the grain were not there (I know this is a grain challenge...)', '2007-03-14 18:43:02.000000', NULL, 1),
(3461852, 484028, 14414, '<td valign="top">I''m not sure how sharp the focus is on the front part of the orchid.</td>', 'I''m not sure how sharp the focus is on the front part of the orchid.', '2007-03-14 18:43:17.000000', NULL, 1),
(3461856, 483930, 67152, '<td valign="top">Nice set up and lighting, but something seems strange with the grain in this photo - it seems to have color to it...I swear I see pinks and greens</td>', 'Nice set up and lighting, but something seems strange with the grain in this photo - it seems to have color to it...I swear I see pinks and greens', '2007-03-14 18:45:46.000000', NULL, 1),
(3461863, 483939, 14414, '<td valign="top">I like this shot, but don''t feel its helped by the grain - it seems to interfere wiht the smoke imho.<br/>6</td>', 'I like this shot, but don''t feel its helped by the grain - it seems to interfere wiht the smoke imho.6', '2007-03-14 18:47:18.000000', NULL, 1),
(3461876, 481878, 67152, '<td valign="top">Neat feel to this photo. This would have probably come off a little better if the person was not ''running into'' the building behind it.  Moving your position a little to the left when shooting this should take care of it.</td>', 'Neat feel to this photo. This would have probably come off a little better if the person was not ''running into'' the building behind it.  Moving your position a little to the left when shooting this should take care of it.', '2007-03-14 18:51:39.000000', NULL, 1),
(3461882, 483964, 67152, '<td valign="top">What an amazing location.  I would have really liked to see this so much better without the grain in color.  Or, converting this to B/W and adding a lot more contrast to give it a 19th century feel.</td>', 'What an amazing location.  I would have really liked to see this so much better without the grain in color.  Or, converting this to B/W and adding a lot more contrast to give it a 19th century feel.', '2007-03-14 18:53:38.000000', NULL, 1),
(3461887, 483753, 67152, '<td valign="top">Nice sharp image - love the colors and textures, but is it missing something?  I really don''t see the grain in this one. Still, it''s a good image. 5</td>', 'Nice sharp image - love the colors and textures, but is it missing something?  I really don''t see the grain in this one. Still, it''s a good image. 5', '2007-03-14 18:55:13.000000', NULL, 1),
(3461892, 481808, 67152, '<td valign="top">The grain is a good choice on this one, but I think this soft lighting would have worked better in sepia or with more contrast.</td>', 'The grain is a good choice on this one, but I think this soft lighting would have worked better in sepia or with more contrast.', '2007-03-14 18:55:55.000000', NULL, 1),
