INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3466625, 483010, 51538, '<td valign="top">One of my favourites from the challenge. I like the simple form in light and shade. 8.</td>', 'One of my favourites from the challenge. I like the simple form in light and shade. 8.', '2007-03-16 14:21:19.000000', NULL, 1),
(3466626, 480608, 51538, '<td valign="top">A good idea since grain immediately implies nostalgia.  8.</td>', 'A good idea since grain immediately implies nostalgia.  8.', '2007-03-16 14:21:25.000000', NULL, 1),
(3466627, 483853, 51538, '<td valign="top">Nicely caught moment.  The cobbles and bridge stones age the image, as does the old Rolls Royce.  edit to add: I think you achieved the grainy effect without using a noise filter.  If that is so, kudos in my opinion to you. 8.</td>', 'Nicely caught moment.  The cobbles and bridge stones age the image, as does the old Rolls Royce.  edit to add: I think you achieved the grainy effect without using a noise filter.  If that is so, kudos in my opinion to you. 8.', '2007-03-16 14:21:42.000000', NULL, 1),
(3466628, 482938, 51538, '<td valign="top">Apt subject and nice in b/w. 8.</td>', 'Apt subject and nice in b/w. 8.', '2007-03-16 14:21:47.000000', NULL, 1),
(3466629, 483841, 51538, '<td valign="top">Nice composition.  The grain is very subtle and fine and that''s the way it should be in this image. 8.</td>', 'Nice composition.  The grain is very subtle and fine and that''s the way it should be in this image. 8.', '2007-03-16 14:21:52.000000', NULL, 1),
(3466630, 483591, 51538, '<td valign="top">Like the composition.  The grain adds something to your photo. 8.</td>', 'Like the composition.  The grain adds something to your photo. 8.', '2007-03-16 14:21:58.000000', NULL, 1),
(3466631, 481959, 51538, '<td valign="top">Nicely composed and the subject is good for the challenge. 8.</td>', 'Nicely composed and the subject is good for the challenge. 8.', '2007-03-16 14:22:06.000000', NULL, 1),
(3466632, 483562, 51538, '<td valign="top">Looks like the ''grain'' is achieved without adding via the PS filter, which is a plus in my mind.  That''s an interesting ragged deckle-edge border too.  Nice work. 8.</td>', 'Looks like the ''grain'' is achieved without adding via the PS filter, which is a plus in my mind.  That''s an interesting ragged deckle-edge border too.  Nice work. 8.', '2007-03-16 14:22:12.000000', NULL, 1),
(3466647, 483662, 34134, '<td valign="top">Beautiful composition. Works well in B&amp;W for me. Great lighting.</td>', 'Beautiful composition. Works well in B&W for me. Great lighting.', '2007-03-16 14:34:51.000000', NULL, 1),
(3466670, 483907, 39664, '<td valign="top">wonderful!</td>', 'wonderful!', '2007-03-16 14:59:26.000000', NULL, 1),
(3466672, 483965, 39664, '<td valign="top">hey I think I know her!  Nice shot! :)</td>', 'hey I think I know her!  Nice shot! :)', '2007-03-16 15:00:21.000000', NULL, 1),
(3466749, 483351, 43156, '<td valign="top">Hmm, I think I know this person. Very powerful portrait and interesting post processing, I like it very much.</td>', 'Hmm, I think I know this person. Very powerful portrait and interesting post processing, I like it very much.', '2007-03-16 15:39:59.000000', NULL, 1),
(3466757, 481306, 43156, '<td valign="top">Very nice capture and noise really adds impact to this image.</td>', 'Very nice capture and noise really adds impact to this image.', '2007-03-16 15:44:34.000000', NULL, 1),
(3466766, 481771, 43156, '<td valign="top">Interesting, whos out of these two people dreaming of her?  Nice use of color and grain.</td>', 'Interesting, whos out of these two people dreaming of her?  Nice use of color and grain.', '2007-03-16 15:48:07.000000', NULL, 1),
(3466772, 483156, 43156, '<td valign="top">Nice cupture and use of grain.</td>', 'Nice cupture and use of grain.', '2007-03-16 15:49:47.000000', NULL, 1),
(3466781, 483979, 43156, '<td valign="top">Nice composition and lighting. Grain really adds impact IMO.</td>', 'Nice composition and lighting. Grain really adds impact IMO.', '2007-03-16 15:51:24.000000', NULL, 1),
(3466825, 483540, 50695, '<td valign="top">the effect of this seems canned, i.e. too staged, but the composition has some good energy to it, and it meets the challenge well. i.e., the grain is part of the canned effect. 6</td>', 'the effect of this seems canned, i.e. too staged, but the composition has some good energy to it, and it meets the challenge well. i.e., the grain is part of the canned effect. 6', '2007-03-16 16:10:45.000000', NULL, 1),
(3466834, 483978, 50695, '<td valign="top">I love the ambiguity of her pose. She''s probably laughing, but she looks like she might be repulsed. And he is absorbed by her. Great candid capture. I don''t know if the grain is adding a lot, but maybe it is giving it a kind of journalistic feel. 7</td>', 'I love the ambiguity of her pose. She''s probably laughing, but she looks like she might be repulsed. And he is absorbed by her. Great candid capture. I don''t know if the grain is adding a lot, but maybe it is giving it a kind of journalistic feel. 7', '2007-03-16 16:12:33.000000', NULL, 1),
(3466842, 481722, 50695, '<td valign="top">Great environmental portrait. Very good backlighting with blocked light source. It surrounds him with blown-out areas of light. Excellent effect. This might work without grain, but the grain is appropriate to the mood and looks "natural", not added on later. 9</td>', 'Great environmental portrait. Very good backlighting with blocked light source. It surrounds him with blown-out areas of light. Excellent effect. This might work without grain, but the grain is appropriate to the mood and looks "natural", not added on later. 9', '2007-03-16 16:14:31.000000', NULL, 1),
(3466844, 483528, 50695, '<td valign="top">I love that big toe! 7</td>', 'I love that big toe! 7', '2007-03-16 16:14:50.000000', NULL, 1),
(3466846, 483085, 50695, '<td valign="top">I like the shadows on the road and the milkiness of this shot. 8</td>', 'I like the shadows on the road and the milkiness of this shot. 8', '2007-03-16 16:15:24.000000', NULL, 1),
(3466853, 482903, 50695, '<td valign="top">Not crazy about your title. The expression has a certain ambiguity to it that you should maintain. Clearly, pain is part of it, but not all.</td>', 'Not crazy about your title. The expression has a certain ambiguity to it that you should maintain. Clearly, pain is part of it, but not all.', '2007-03-16 16:16:36.000000', NULL, 1),
(3466857, 483748, 50695, '<td valign="top">I would love this is the only "grain" were on the tv(?) screen (speaker?). but then you would have gotten a bunch of dnmc''s. but it would have been awesome! heck, I''ll give you a 7 anyway.</td>', 'I would love this is the only "grain" were on the tv(?) screen (speaker?). but then you would have gotten a bunch of dnmc''s. but it would have been awesome! heck, I''ll give you a 7 anyway.', '2007-03-16 16:17:53.000000', NULL, 1),
(3466858, 482886, 50695, '<td valign="top">love the processing on this and the strong dark shapes running up the center. 8</td>', 'love the processing on this and the strong dark shapes running up the center. 8', '2007-03-16 16:18:29.000000', NULL, 1),
(3466865, 483965, 50695, '<td valign="top">idnic? good to see a black background instead of a white one. Seems like just a touch too much glow here. Otherwise, you''ve really captured the feel of a "boxing shot." Oh, except for the make-up. Vanity, thy name is Self Portait! 6</td>', 'idnic? good to see a black background instead of a white one. Seems like just a touch too much glow here. Otherwise, you''ve really captured the feel of a "boxing shot." Oh, except for the make-up. Vanity, thy name is Self Portait! 6', '2007-03-16 16:20:16.000000', NULL, 1),
(3466868, 483179, 50695, '<td valign="top">IR is not as bad with some grain on it! 6</td>', 'IR is not as bad with some grain on it! 6', '2007-03-16 16:21:26.000000', NULL, 1),
(3466872, 484010, 50695, '<td valign="top">the shadow seems to have ruled your composition. It''s a great shot except for that. I would try a tighter or a wider shot. I won''t know until I see it! Not helpful, I know. 6</td>', 'the shadow seems to have ruled your composition. It''s a great shot except for that. I would try a tighter or a wider shot. I won''t know until I see it! Not helpful, I know. 6', '2007-03-16 16:23:01.000000', NULL, 1),
(3466873, 482413, 50695, '<td valign="top">I have a feeling this is more spectacular without the grain. ub it still merits a 7.</td>', 'I have a feeling this is more spectacular without the grain. ub it still merits a 7.', '2007-03-16 16:23:58.000000', NULL, 1),
(3466875, 483519, 50695, '<td valign="top">I said she was a fine upstanding woman.</td>', 'I said she was a fine upstanding woman.', '2007-03-16 16:24:44.000000', NULL, 1),
(3466877, 483638, 50695, '<td valign="top">the grain helps! It easily adds 2 points to this image. 7</td>', 'the grain helps! It easily adds 2 points to this image. 7', '2007-03-16 16:25:25.000000', NULL, 1),
(3466880, 483907, 50695, '<td valign="top">fascinating enigmatic image. almost Omen-like. 7</td>', 'fascinating enigmatic image. almost Omen-like. 7', '2007-03-16 16:25:58.000000', NULL, 1),
(3466883, 483762, 50695, '<td valign="top">beautiful find and/or set-up. The grain works very well with it. 9</td>', 'beautiful find and/or set-up. The grain works very well with it. 9', '2007-03-16 16:26:23.000000', NULL, 1),
(3466887, 483147, 50695, '<td valign="top">what a terrific candid. classic exuberance. brings back the 1930''s and I wasn''t even alive then. The grain is perfect for this, I think. It kind of blocks me from thinking I''m in their intimate space. 9</td>', 'what a terrific candid. classic exuberance. brings back the 1930''s and I wasn''t even alive then. The grain is perfect for this, I think. It kind of blocks me from thinking I''m in their intimate space. 9', '2007-03-16 16:27:55.000000', NULL, 1),
(3466888, 480849, 50695, '<td valign="top">this is on the verge of becoming a dpc cliche, but there''s something about this one, and the grain only helps it along. 9</td>', 'this is on the verge of becoming a dpc cliche, but there''s something about this one, and the grain only helps it along. 9', '2007-03-16 16:28:35.000000', NULL, 1),
(3466890, 483989, 50695, '<td valign="top">enjoyable composition. 7</td>', 'enjoyable composition. 7', '2007-03-16 16:28:49.000000', NULL, 1),
(3466893, 481521, 50695, '<td valign="top">grain helps the nostalgic style of this. 7</td>', 'grain helps the nostalgic style of this. 7', '2007-03-16 16:29:15.000000', NULL, 1),
(3466900, 483392, 50695, '<td valign="top">if this is an art exhibit, you get an 8. If this is a factory tour, you get a 10. I''m thinking art exhibit.</td>', 'if this is an art exhibit, you get an 8. If this is a factory tour, you get a 10. I''m thinking art exhibit.', '2007-03-16 16:30:56.000000', NULL, 1),
