(3467618, 481080, 66597, '<td valign="top">Moody and beautiful. The white area may be a little too bright, but otherwise near perfection. 8.</td>', 'Moody and beautiful. The white area may be a little too bright, but otherwise near perfection. 8.', '2007-03-16 22:54:26.000000', NULL, 1),
