(3467623, 483748, 66597, '<td valign="top">Love the post-modern look here. Bumping from 7 to 8. The textures are great with the grain.</td>', 'Love the post-modern look here. Bumping from 7 to 8. The textures are great with the grain.', '2007-03-16 22:55:06.000000', NULL, 1),
(3467627, 483988, 66597, '<td valign="top">A very well done portrait indeed. I appreciate that the grain is subtle here. Bumping to 8.</td>', 'A very well done portrait indeed. I appreciate that the grain is subtle here. Bumping to 8.', '2007-03-16 22:55:28.000000', NULL, 1),
(3467628, 484014, 66597, '<td valign="top">I love environmental portraits and this one is well done. I love how the focus is on the bottles and not the face.</td>', 'I love environmental portraits and this one is well done. I love how the focus is on the bottles and not the face.', '2007-03-16 22:55:34.000000', NULL, 1),
(3467630, 483314, 66597, '<td valign="top">Very cool! Love the creativity in this - I bet Hitchcock would approve :-)</td>', 'Very cool! Love the creativity in this - I bet Hitchcock would approve :-)', '2007-03-16 22:55:43.000000', NULL, 1),
(3467631, 483560, 66597, '<td valign="top">Simple and lovely, though I''m not sure the grain adds anything to this photo. Your lighting is superb either way.</td>', 'Simple and lovely, though I''m not sure the grain adds anything to this photo. Your lighting is superb either way.', '2007-03-16 22:55:50.000000', NULL, 1),
(3467634, 483200, 66597, '<td valign="top">Not to nit, but by any chance did you mean "The Moment Before I Walk Down the Aisle"? I wasn''t sure if it was an intentional play on words? Anyway, really beautiful shot. Love the frame job and muted lashes.</td>', 'Not to nit, but by any chance did you mean "The Moment Before I Walk Down the Aisle"? I wasn''t sure if it was an intentional play on words? Anyway, really beautiful shot. Love the frame job and muted lashes.', '2007-03-16 22:56:18.000000', NULL, 1),
(3467635, 483991, 66597, '<td valign="top">Lovely portrait. The eyes capture attention, as they should in this type of photo.</td>', 'Lovely portrait. The eyes capture attention, as they should in this type of photo.', '2007-03-16 22:56:23.000000', NULL, 1),
(3467637, 482514, 66597, '<td valign="top">I love the angles and perspective on this. Interesting and well done.</td>', 'I love the angles and perspective on this. Interesting and well done.', '2007-03-16 22:56:40.000000', NULL, 1),
