(3470036, 481616, 66384, '<td valign="top">Don''t see the grain. Actually don''t see much on my monitor. This image is too small and dark.</td>', 'Don''t see the grain. Actually don''t see much on my monitor. This image is too small and dark.', '2007-03-18 13:46:37.000000', NULL, 1),
(3470038, 482093, 56494, '<td valign="top">haha!</td>', 'haha!', '2007-03-18 13:48:40.000000', NULL, 1),
(3470039, 482015, 66384, '<td valign="top">This image looks very clear to me. I don''t see the grain -- must be too subtle for my monitor or eyes. It is a lovely photo, with very nice light and composition.</td>', 'This image looks very clear to me. I don''t see the grain -- must be too subtle for my monitor or eyes. It is a lovely photo, with very nice light and composition.', '2007-03-18 13:49:02.000000', NULL, 1),
(3470041, 483829, 56494, '<td valign="top">that''s a good shot! I used to believe in stuff under the bed.</td>', 'that''s a good shot! I used to believe in stuff under the bed.', '2007-03-18 13:49:35.000000', NULL, 1),
(3470043, 482322, 66384, '<td valign="top">Focus looks a little soft, and I don''t see the grain. Cute girl and nice costume though.</td>', 'Focus looks a little soft, and I don''t see the grain. Cute girl and nice costume though.', '2007-03-18 13:50:27.000000', NULL, 1),
(3470044, 483839, 56494, '<td valign="top">nice, i like it</td>', 'nice, i like it', '2007-03-18 13:50:36.000000', NULL, 1),
(3470046, 483314, 30982, '<td valign="top">I''m not sure Grain is the right challenge for this, but it''s an awesome shot.</td>', 'I''m not sure Grain is the right challenge for this, but it''s an awesome shot.', '2007-03-18 13:51:37.000000', NULL, 1),
(3470051, 483200, 66384, '<td valign="top">Without the title I wouldn''t have been able to make out what this is. Interesting idea, and the grain adds to the effect, but I think is is too blurred to work, and the burned-edge border is distracting.</td>', 'Without the title I wouldn''t have been able to make out what this is. Interesting idea, and the grain adds to the effect, but I think is is too blurred to work, and the burned-edge border is distracting.', '2007-03-18 13:54:00.000000', NULL, 1),
