(3474380, 482306, 10943, '<td valign="top">This is nice, but I see more blur than noise.</td>', 'This is nice, but I see more blur than noise.', '2007-03-19 23:38:56.000000', NULL, 1),
(3474522, 483839, 52549, '<td valign="top">Beautiful, love the composition and the colour.</td>', 'Beautiful, love the composition and the colour.', '2007-03-20 01:47:10.000000', NULL, 1),
(3474523, 481721, 52549, '<td valign="top">This composition suits grain to a "T". Super.</td>', 'This composition suits grain to a "T". Super.', '2007-03-20 01:48:30.000000', NULL, 1),
(3474526, 483797, 52549, '<td valign="top">Excellent colour and composition. Love the feeling of solitude that comes over.</td>', 'Excellent colour and composition. Love the feeling of solitude that comes over.', '2007-03-20 01:50:23.000000', NULL, 1),
(3474528, 483266, 52549, '<td valign="top">Perfect for grain. Great shot.</td>', 'Perfect for grain. Great shot.', '2007-03-20 01:51:16.000000', NULL, 1),
