INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3474534, 482465, 52549, '<td valign="top">Great colour, but without the title, it would be difficult to make out what you''ve photographed. Good luck.</td>', 'Great colour, but without the title, it would be difficult to make out what you''ve photographed. Good luck.', '2007-03-20 01:55:11.000000', NULL, 1),
(3474536, 481149, 52549, '<td valign="top">Brilliant! Hope you get a top 10 with this.</td>', 'Brilliant! Hope you get a top 10 with this.', '2007-03-20 01:56:11.000000', NULL, 1),
(3474538, 483582, 52549, '<td valign="top">Whatever it is, it''s a beautiful shot.</td>', 'Whatever it is, it''s a beautiful shot.', '2007-03-20 01:56:54.000000', NULL, 1),
(3474552, 481978, 54778, '<td valign="top">Nice tones.. and framing..</td>', 'Nice tones.. and framing..', '2007-03-20 02:11:23.000000', NULL, 1),
(3474637, 483933, 46598, '<td valign="top">I like the photo. But I think it needs to be even more dramatic.</td>', 'I like the photo. But I think it needs to be even more dramatic.', '2007-03-20 04:53:23.000000', NULL, 1),
(3474659, 482326, 46598, '<td valign="top">woah! cool!</td>', 'woah! cool!', '2007-03-20 05:07:33.000000', NULL, 1),
(3474662, 483031, 46598, '<td valign="top">Hummm I feel almost sorry to say this since I like the photo, but the grain doesn''t add, it takes away in this case...</td>', 'Hummm I feel almost sorry to say this since I like the photo, but the grain doesn''t add, it takes away in this case...', '2007-03-20 05:09:08.000000', NULL, 1),
(3474725, 483345, 36999, '<td valign="top">very pretty colors nice texture too</td>', 'very pretty colors nice texture too', '2007-03-20 06:08:28.000000', NULL, 1),
(3474737, 483163, 66201, '<td valign="top">Wild, dramatic, so atmospheric.</td>', 'Wild, dramatic, so atmospheric.', '2007-03-20 06:18:59.000000', NULL, 1),
(3474746, 480727, 6999, '<td valign="top">These front steps of St Paul''s have a certain appeal - I''ve never quite been able to nail it, photographically: I''m not entirely sure you''ve succeeded either. For me, I think the issue is that I don''t see a story here, a narrative; nor do I find a particular interest in the groups of people - it''s just all so very ordinary. That, of course, has its own appeal in a way, as a kind of document; but it''s a photograph that one could take any and every day if one so wished, with much the same results. It is, however, technically unimpeachable - exposure and control is good, and some grain brings something to it. For my taste it could have more contrast.</td>', 'These front steps of St Paul''s have a certain appeal - I''ve never quite been able to nail it, photographically: I''m not entirely sure you''ve succeeded either. For me, I think the issue is that I don''t see a story here, a narrative; nor do I find a particular interest in the groups of people - it''s just all so very ordinary. That, of course, has its own appeal in a way, as a kind of document; but it''s a photograph that one could take any and every day if one so wished, with much the same results. It is, however, technically unimpeachable - exposure and control is good, and some grain brings something to it. For my taste it could have more contrast.', '2007-03-20 06:39:43.000000', NULL, 1),
(3474748, 481664, 64086, '<td valign="top">The idea of this is very good. I like the color and texture. The warm light on the closest door. I think the sky without detail in the upper left detracts from the image. Maybe a lower vantage point or different angle would improve this.</td>', 'The idea of this is very good. I like the color and texture. The warm light on the closest door. I think the sky without detail in the upper left detracts from the image. Maybe a lower vantage point or different angle would improve this.', '2007-03-20 06:45:41.000000', NULL, 1),
(3474879, 483570, 53130, '<td valign="top">love this one!!</td>', 'love this one!!', '2007-03-20 09:35:35.000000', NULL, 1),
(3474891, 482280, 20357, '<td valign="top">interesting subject. the additional noise/grain, however, blurrs what should (IMO) a clear and crisp depiction of the (actual) grain, taking away instead of adding to the photo</td>', 'interesting subject. the additional noise/grain, however, blurrs what should (IMO) a clear and crisp depiction of the (actual) grain, taking away instead of adding to the photo', '2007-03-20 09:44:41.000000', NULL, 1),
(3474899, 482642, 20357, '<td valign="top">what a cool subject to photograph. it seems as though you sacrificed saturation and vibrancy, leaving grain superimposed on a washed-out photo. also, im curious about your choice in sepia-tone: this setting seems like it would have a really pleasing color palette!</td>', 'what a cool subject to photograph. it seems as though you sacrificed saturation and vibrancy, leaving grain superimposed on a washed-out photo. also, im curious about your choice in sepia-tone: this setting seems like it would have a really pleasing color palette!', '2007-03-20 09:48:14.000000', NULL, 1),
(3474905, 481978, 20357, '<td valign="top">i love the contrast and your use of grain - many submissions in this category appear washed-out, the impact sacrificed for grain rather than enhanced by it. however, your composition could be more engaging - what am I looking at? where are you leading my eyes?</td>', 'i love the contrast and your use of grain - many submissions in this category appear washed-out, the impact sacrificed for grain rather than enhanced by it. however, your composition could be more engaging - what am I looking at? where are you leading my eyes?', '2007-03-20 09:49:51.000000', NULL, 1),
(3474910, 482326, 20357, '<td valign="top">wow. fantastic composition, and the grain really adds a visceral grit to your photo. i love the occluded sun working through the clouds, and it''s positioned perfectly against the vessel. my pick for a ribbon!</td>', 'wow. fantastic composition, and the grain really adds a visceral grit to your photo. i love the occluded sun working through the clouds, and it''s positioned perfectly against the vessel. my pick for a ribbon!', '2007-03-20 09:51:36.000000', NULL, 1),
(3474919, 483727, 20357, '<td valign="top">your contrast color and grain really make pop an otherwise mundane subject! the aesthetic seems to lend the ostrich a wise, contemplative aura.</td>', 'your contrast color and grain really make pop an otherwise mundane subject! the aesthetic seems to lend the ostrich a wise, contemplative aura.', '2007-03-20 09:54:29.000000', NULL, 1),
(3474920, 483735, 62989, '<td valign="top">really ?</td>', 'really ?', '2007-03-20 09:54:51.000000', NULL, 1),
(3474921, 481194, 20357, '<td valign="top">great choice for a subject, i like your composition as well. the "37 PLY" distracts a bit, but your grain really adds to the photo.</td>', 'great choice for a subject, i like your composition as well. the "37 PLY" distracts a bit, but your grain really adds to the photo.', '2007-03-20 09:55:37.000000', NULL, 1),
(3474922, 483638, 20357, '<td valign="top">great shot! most entries seem to automatically meld grain with monotone, but here you demonstrate great use of grain with color! my pick for a ribbon.</td>', 'great shot! most entries seem to automatically meld grain with monotone, but here you demonstrate great use of grain with color! my pick for a ribbon.', '2007-03-20 09:58:05.000000', NULL, 1),
(3474924, 482097, 62989, '<td valign="top">Surely it should be blue ? and dead ?</td>', 'Surely it should be blue ? and dead ?', '2007-03-20 09:58:49.000000', NULL, 1),
(3474928, 481535, 20357, '<td valign="top">woah. cool effect. your photo has an unmistakable painting quality, which i''m curious how you managed to achieve.</td>', 'woah. cool effect. your photo has an unmistakable painting quality, which i''m curious how you managed to achieve.', '2007-03-20 09:59:38.000000', NULL, 1),
(3474941, 483665, 72839, '<td valign="top">This sort of looks like a snapshot, and i see little if any grain in the image!</td>', 'This sort of looks like a snapshot, and i see little if any grain in the image!', '2007-03-20 10:06:15.000000', NULL, 1),
(3474942, 483633, 72839, '<td valign="top">There is too much background, but the colors are nice and there is a nice balance of grain.</td>', 'There is too much background, but the colors are nice and there is a nice balance of grain.', '2007-03-20 10:06:58.000000', NULL, 1),
(3474943, 483155, 72839, '<td valign="top">I really like the idea and there is a wide variety of colors.Love it!!</td>', 'I really like the idea and there is a wide variety of colors.Love it!!', '2007-03-20 10:07:32.000000', NULL, 1),
(3474945, 480901, 72839, '<td valign="top">I actually really like this image, it fells like a picture from a storybook. I love the feeling this image gives off and the colors are so nice and warm.</td>', 'I actually really like this image, it fells like a picture from a storybook. I love the feeling this image gives off and the colors are so nice and warm.', '2007-03-20 10:08:23.000000', NULL, 1),
(3474948, 483301, 6999, '<td valign="top">I like the slightly mad composition here: the differing angles of hands and fingers, the partial inclusion of the head, the slightly unusual positioning within frame. Whilst perhaps not a ''great'' image, it''s certainly thoughtful and interesting.</td>', 'I like the slightly mad composition here: the differing angles of hands and fingers, the partial inclusion of the head, the slightly unusual positioning within frame. Whilst perhaps not a ''great'' image, it''s certainly thoughtful and interesting.', '2007-03-20 10:10:29.000000', NULL, 1),
(3474955, 481978, 69368, '<td valign="top">aaah! Looks like a winner! Great work!</td>', 'aaah! Looks like a winner! Great work!', '2007-03-20 10:13:54.000000', NULL, 1),
(3474958, 481444, 69368, '<td valign="top">beautiful!</td>', 'beautiful!', '2007-03-20 10:14:47.000000', NULL, 1),
(3474966, 481180, 69368, '<td valign="top">a little bit too centered, IMO. Otherwise a great shot. Could be in the Top 10! Good luck! - 8 -</td>', 'a little bit too centered, IMO. Otherwise a great shot. Could be in the Top 10! Good luck! - 8 -', '2007-03-20 10:18:17.000000', NULL, 1),
(3475020, 481193, 72839, '<td valign="top">This picture is absolutely adorable. I love the coloring and and the shading. Beautiful!</td>', 'This picture is absolutely adorable. I love the coloring and and the shading. Beautiful!', '2007-03-20 10:52:54.000000', NULL, 1),
(3475023, 481464, 72839, '<td valign="top">Too much grain in this one. Also, I think you could have taken it from a more interesting angle, instead of straight on.</td>', 'Too much grain in this one. Also, I think you could have taken it from a more interesting angle, instead of straight on.', '2007-03-20 10:53:36.000000', NULL, 1),
(3475027, 483564, 56000, '<td valign="top">I would have liked to have seen more of the chair and would be better in B/W so you don''t see the color noise.  6</td>', 'I would have liked to have seen more of the chair and would be better in B/W so you don''t see the color noise.  6', '2007-03-20 10:55:00.000000', NULL, 1),
(3475030, 482268, 72841, '<td valign="top">I really like the colors and crispness to this image.</td>', 'I really like the colors and crispness to this image.', '2007-03-20 10:55:20.000000', NULL, 1),
(3475034, 481657, 74747, '<td valign="top">I really like the grain in this picture and think it adds a lot.</td>', 'I really like the grain in this picture and think it adds a lot.', '2007-03-20 10:56:32.000000', NULL, 1),
(3475036, 483181, 72841, '<td valign="top">I like the soft hues of grey to this image. Very pretty.</td>', 'I like the soft hues of grey to this image. Very pretty.', '2007-03-20 10:56:59.000000', NULL, 1),
