(3475558, 483308, 15574, '<td valign="top">Awesome looking image, especially how you could do this in basic editing.</td>', 'Awesome looking image, especially how you could do this in basic editing.', '2007-03-20 15:05:24.000000', NULL, 1),
(3475560, 483530, 52549, '<td valign="top">Very pretty, beautiful colours.</td>', 'Very pretty, beautiful colours.', '2007-03-20 15:06:06.000000', NULL, 1),
(3475561, 483829, 15574, '<td valign="top">Nice set up and lighting, that would be awesome if it a monster hand reaching instead.</td>', 'Nice set up and lighting, that would be awesome if it a monster hand reaching instead.', '2007-03-20 15:06:56.000000', NULL, 1),
(3475562, 483914, 52549, '<td valign="top">This probably looks even better without the grain, but it still looks great.</td>', 'This probably looks even better without the grain, but it still looks great.', '2007-03-20 15:07:53.000000', NULL, 1),
(3475564, 483809, 52549, '<td valign="top">Really beautiful.</td>', 'Really beautiful.', '2007-03-20 15:08:17.000000', NULL, 1),
(3475568, 483010, 52549, '<td valign="top">Amazing shot - great lighting.</td>', 'Amazing shot - great lighting.', '2007-03-20 15:09:14.000000', NULL, 1),
(3475571, 483540, 52549, '<td valign="top">Cool. Love the composition and the colours.</td>', 'Cool. Love the composition and the colours.', '2007-03-20 15:10:06.000000', NULL, 1),
(3475599, 481981, 73884, '<td valign="top">Very inspired! I like the color contrast (in fact all high key flower shots impress me). If it is not 10 is because of the little spot next to the vase. 9</td>', 'Very inspired! I like the color contrast (in fact all high key flower shots impress me). If it is not 10 is because of the little spot next to the vase. 9', '2007-03-20 15:28:36.000000', NULL, 1),
(3475606, 482326, 73884, '<td valign="top">Wow... very impressive! And yes, I belive that the grain does improve the eerie feeling.</td>', 'Wow... very impressive! And yes, I belive that the grain does improve the eerie feeling.', '2007-03-20 15:32:13.000000', NULL, 1),
(3475612, 483929, 73884, '<td valign="top">I like the color combination and the geometrical patterns (diagonals, lines and arches). The grain gives an "old castle" feeling. 8</td>', 'I like the color combination and the geometrical patterns (diagonals, lines and arches). The grain gives an "old castle" feeling. 8', '2007-03-20 15:35:35.000000', NULL, 1),
(3475642, 481181, 62906, '<td valign="top">A bit too dark but, I love the concept.  You can just make out the shapes of the other pieces as they are cast onto the ones in front of them.  Maybe would have worked in color?</td>', 'A bit too dark but, I love the concept.  You can just make out the shapes of the other pieces as they are cast onto the ones in front of them.  Maybe would have worked in color?', '2007-03-20 15:42:41.000000', NULL, 1),
(3475649, 483638, 62906, '<td valign="top">Great color pop, even with the dulling down with the grain.  The petals still have nice clean lines.</td>', 'Great color pop, even with the dulling down with the grain.  The petals still have nice clean lines.', '2007-03-20 15:45:32.000000', NULL, 1),
(3475661, 481535, 62906, '<td valign="top">Looks almost like the background is fading away.  Gives the sense of realism giving way to impressionism and the girl skating in her own little world.  Interesting use of grain, I like it!</td>', 'Looks almost like the background is fading away.  Gives the sense of realism giving way to impressionism and the girl skating in her own little world.  Interesting use of grain, I like it!', '2007-03-20 15:55:37.000000', NULL, 1),
(3475663, 481888, 62906, '<td valign="top">Very retro look, this could have easily been taken 40yrs ago.</td>', 'Very retro look, this could have easily been taken 40yrs ago.', '2007-03-20 15:56:45.000000', NULL, 1),
(3475676, 483899, 62906, '<td valign="top">I''d like to see more grain, it looks like just enough was added to qualify.  However, the image itself is simply beautiful and truly does beckon me to follow down such a road.</td>', 'I''d like to see more grain, it looks like just enough was added to qualify.  However, the image itself is simply beautiful and truly does beckon me to follow down such a road.', '2007-03-20 16:06:13.000000', NULL, 1),
(3475685, 483925, 62906, '<td valign="top">very surreal and tastefully abstract.  good work!</td>', 'very surreal and tastefully abstract.  good work!', '2007-03-20 16:09:28.000000', NULL, 1),
(3475689, 483156, 62906, '<td valign="top">not sure about the addition of the photographer at the bottom.  I guess it sets it apart from any myriad of similar pictures but, I''m not sure it helps with the overall photograph, I find it beautiful without him.  A very classically beautiful picture otherwise, nice job.</td>', 'not sure about the addition of the photographer at the bottom.  I guess it sets it apart from any myriad of similar pictures but, I''m not sure it helps with the overall photograph, I find it beautiful without him.  A very classically beautiful picture otherwise, nice job.', '2007-03-20 16:12:26.000000', NULL, 1),
(3475716, 483727, 72839, '<td valign="top">Interesting subject, you photographed just enough! nice color and very in focus!</td>', 'Interesting subject, you photographed just enough! nice color and very in focus!', '2007-03-20 16:23:43.000000', NULL, 1),
(3475723, 483345, 72839, '<td valign="top">with the grain and the water, the picture is sort of confusing and unclear, but I like the colors and this was a really cool idea!</td>', 'with the grain and the water, the picture is sort of confusing and unclear, but I like the colors and this was a really cool idea!', '2007-03-20 16:25:56.000000', NULL, 1),
(3475733, 484019, 72839, '<td valign="top">I like the white background, it puts a lot of emphasis on the subject, but i think you should have tried more grain. but the lighting rocks!</td>', 'I like the white background, it puts a lot of emphasis on the subject, but i think you should have tried more grain. but the lighting rocks!', '2007-03-20 16:32:21.000000', NULL, 1),
(3475747, 483989, 72839, '<td valign="top">I love the neutral colors and the bright blue background together, also there is a good amount of grain balance.</td>', 'I love the neutral colors and the bright blue background together, also there is a good amount of grain balance.', '2007-03-20 16:38:02.000000', NULL, 1),
(3475754, 483310, 62906, '<td valign="top">a bit heavy on the grain.  I think the photo is otherwise is great and would have retained and perhaps enhanced it''s dramatic effect with a bit less noise.</td>', 'a bit heavy on the grain.  I think the photo is otherwise is great and would have retained and perhaps enhanced it''s dramatic effect with a bit less noise.', '2007-03-20 16:40:14.000000', NULL, 1),
(3475756, 482642, 72839, '<td valign="top">this is sort of washed out, but i think it makes it look interesting, it gives it a very old-timey feeling. there is a nice balance of color.</td>', 'this is sort of washed out, but i think it makes it look interesting, it gives it a very old-timey feeling. there is a nice balance of color.', '2007-03-20 16:40:30.000000', NULL, 1),
