INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3477120, 483829, 45475, '<td valign="top">No no, I think the darkness is perfect. In fact, it could probably stand a bit more to add to the fear and trepidation I feel from this. Sad that it''s so underrated :( I gave it an 8.</td>', 'No no, I think the darkness is perfect. In fact, it could probably stand a bit more to add to the fear and trepidation I feel from this. Sad that it''s so underrated :( I gave it an 8.', '2007-03-21 02:04:57.000000', NULL, 0),
(3477122, 483765, 22975, '<td valign="top">this might be my favorite photo that i''ve seen on this site in a looooong time.  what an eye you have.</td>', 'this might be my favorite photo that i''ve seen on this site in a looooong time.  what an eye you have.', '2007-03-21 02:07:01.000000', NULL, 0),
(3477123, 482514, 23394, '<td valign="top">i had a feeling this was yours.  nothing else comes close.</td>', 'i had a feeling this was yours.  nothing else comes close.', '2007-03-21 02:07:26.000000', NULL, 0),
(3477124, 483853, 23394, '<td valign="top">nicely done!  i thought i recognized that signature processing ;-)</td>', 'nicely done!  i thought i recognized that signature processing ;-)', '2007-03-21 02:08:24.000000', NULL, 0),
(3477126, 483821, 68504, '<td valign="top">Beautifully composed; and the browns and whites (lines, masses, textures)work really well.  (Not sure I agree with posthumous, but it would be interesting to see it without grain).</td>', 'Beautifully composed; and the browns and whites (lines, masses, textures)work really well.  (Not sure I agree with posthumous, but it would be interesting to see it without grain).', '2007-03-21 02:08:54.000000', NULL, 0),
(3477127, 483299, 53316, '<td valign="top">I love the darkness. I think maybe non-calibrated moitors hurt you, as you did get comments saying that people could barely see things.  It''s always a risk entering something so dark.  But the way that the light comes in.. the angle of it, and the spot where it appears.. it is all very lovely.  I agree that maybe there is a tad too much negative space - perhaps a tighter crop on the bottom and right would be better. I love the blue tones as well - helps with the cold, moody feel.</td>', 'I love the darkness. I think maybe non-calibrated moitors hurt you, as you did get comments saying that people could barely see things.  It''s always a risk entering something so dark.  But the way that the light comes in.. the angle of it, and the spot where it appears.. it is all very lovely.  I agree that maybe there is a tad too much negative space - perhaps a tighter crop on the bottom and right would be better. I love the blue tones as well - helps with the cold, moody feel.', '2007-03-21 02:08:55.000000', NULL, 0),
(3477129, 483317, 61336, '<td valign="top">Well done Antoni. Congrats on the ribbon.<br/><br/><i>Message edited by author 2007-03-21 02:10:45.</i></td>', 'Well done Antoni. Congrats on the ribbon.', '2007-03-21 02:09:53.000000', '2007-03-21 02:10:45.000000', 0),
(3477130, 483314, 23394, '<td valign="top">please don''t take your score and finish to heart.  this is top-notch work--keep it up!</td>', 'please don''t take your score and finish to heart.  this is top-notch work--keep it up!', '2007-03-21 02:10:26.000000', NULL, 0),
(3477132, 483378, 67145, '<td valign="top">really love this image ... its just excellent .. love the composition and the subject ...   this should''ve done heaps better in the challenge ... certain elements in this photograph remind me of my ''fill the frame'' image ... ..</td>', 'really love this image ... its just excellent .. love the composition and the subject ...   this should''ve done heaps better in the challenge ... certain elements in this photograph remind me of my ''fill the frame'' image ... ..', '2007-03-21 02:11:54.000000', NULL, 0),
