INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3479407, 482389, 66384, '<td valign="top">Good shot, good score, good finish. Congratulations. There''s a nice feel to this. The man''s head down with weariness, and his age and weakness shown by the need for a cart to carry a violin. The lighting with the long shadows adds to the sense of weariness at the end of the day. The grain also adds to the mood and photo journalistic style.</td>', 'Good shot, good score, good finish. Congratulations. There''s a nice feel to this. The man''s head down with weariness, and his age and weakness shown by the need for a cart to carry a violin. The lighting with the long shadows adds to the sense of weariness at the end of the day. The grain also adds to the mood and photo journalistic style.', '2007-03-21 18:39:15.000000', NULL, 0),
(3479418, 483082, 66384, '<td valign="top">The focus is nice and sharp so that should have given you some good votes from the focus police. I don''t really think the noise is very effective on this pic; maybe because it is too uniform across the whole image. I gave it a 7 because I thought the lighting, focus, contrast, and composition were good.</td>', 'The focus is nice and sharp so that should have given you some good votes from the focus police. I don''t really think the noise is very effective on this pic; maybe because it is too uniform across the whole image. I gave it a 7 because I thought the lighting, focus, contrast, and composition were good.', '2007-03-21 18:45:49.000000', NULL, 0),
(3479421, 480710, 66384, '<td valign="top">I like the golden tone.</td>', 'I like the golden tone.', '2007-03-21 18:48:37.000000', NULL, 0),
(3479430, 483701, 66384, '<td valign="top">This is a strongly sad image. Such a lot is being said here. The grain is a good addition.</td>', 'This is a strongly sad image. Such a lot is being said here. The grain is a good addition.', '2007-03-21 18:51:33.000000', NULL, 0),
(3479453, 482713, 67152, '<td valign="top">I think this could have come off more dramatic (and that is what scores well here) with a better lighting on the bridge itself.  There was decent contrast in the image - especially on the reflection, but the majority of the image seemed a little flat.  In addition, the cropping was a little tight - I think more sky in the image may have helped as well.</td>', 'I think this could have come off more dramatic (and that is what scores well here) with a better lighting on the bridge itself.  There was decent contrast in the image - especially on the reflection, but the majority of the image seemed a little flat.  In addition, the cropping was a little tight - I think more sky in the image may have helped as well.', '2007-03-21 19:00:20.000000', NULL, 0),
(3479582, 480626, 53316, '<td valign="top">I love the composition and think it''s so cool you''re working to do more of the framing in-camera.</td>', 'I love the composition and think it''s so cool you''re working to do more of the framing in-camera.', '2007-03-21 20:04:50.000000', NULL, 0),
(3479612, 481149, 54044, '<td valign="top">thanks to all for the comments and votes, every time i am getting closer .me thinks</td>', 'thanks to all for the comments and votes, every time i am getting closer .me thinks', '2007-03-21 20:25:19.000000', NULL, 0),
(3479639, 481080, 29293, '<td valign="top">very nice and a lovely model!!!</td>', 'very nice and a lovely model!!!', '2007-03-21 20:41:02.000000', NULL, 0),
(3479648, 482713, 29293, '<td valign="top">i thot it was a bit flat, not real contrast.  and my eye doesnt flow to anywhere in the frame.  keep pushing it!</td>', 'i thot it was a bit flat, not real contrast.  and my eye doesnt flow to anywhere in the frame.  keep pushing it!', '2007-03-21 20:45:25.000000', NULL, 0),
(3479773, 482713, 2764, '<td valign="top">I wonder if you suffered from "voter monitor calibration syndrome"  It seems a bit dark on my monitor.  Darkish images appear too dark on a lot of other monitors and suffer for it.  When id doubt, enter a brighter shot or be prepared for a lower score.<br/> <br/>You have a dramatic leading ling here, the surface where the bridge and reflection meet, and the decreasing size of the ovals they make.  But you line leads the viewer to nothing.  Are those birds on the opposite shore?  I can''t make it out.  So, in a speed vote, if your leading line leads the viewer to nothing, his sye continues on out of the frame and his finger says "Next" without giving the rest of the photo the attention it might deserve.</td>', 'I wonder if you suffered from "voter monitor calibration syndrome"  It seems a bit dark on my monitor.  Darkish images appear too dark on a lot of other monitors and suffer for it.  When id doubt, enter a brighter shot or be prepared for a lower score. You have a dramatic leading ling here, the surface where the bridge and reflection meet, and the decreasing size of the ovals they make.  But you line leads the viewer to nothing.  Are those birds on the opposite shore?  I can''t make it out.  So, in a speed vote, if your leading line leads the viewer to nothing, his sye continues on out of the frame and his finger says "Next" without giving the rest of the photo the attention it might deserve.', '2007-03-21 21:32:21.000000', NULL, 0),
(3479819, 483540, 23430, '<td valign="top">Great shot. I like the colours and tones brought out very nicely in your processing.</td>', 'Great shot. I like the colours and tones brought out very nicely in your processing.', '2007-03-21 21:48:11.000000', NULL, 0),
(3479828, 483562, 23430, '<td valign="top">Nice scene and nicely processed.</td>', 'Nice scene and nicely processed.', '2007-03-21 21:55:47.000000', NULL, 0),
(3479833, 483394, 23430, '<td valign="top">This is very well done. The DOF draws your eyes to the gun point. The grain enhances the mood. Well done.</td>', 'This is very well done. The DOF draws your eyes to the gun point. The grain enhances the mood. Well done.', '2007-03-21 21:57:20.000000', NULL, 0),
