(3741881, 483634, 31637, '<td valign="top">Very emotive photo. Usually young people do not have as much faith as older ones, you are wise beyond your years. The fog adds to this. The angle is perfect since the sun is blocked.</td>', 'Very emotive photo. Usually young people do not have as much faith as older ones, you are wise beyond your years. The fog adds to this. The angle is perfect since the sun is blocked.', '2007-06-05 14:11:16.000000', NULL, 0),
(3760992, 483683, 64568, '<td valign="top">this is a great grain shot, love everything about it...especially the person outside the window, well done ;-)</td>', 'this is a great grain shot, love everything about it...especially the person outside the window, well done ;-)', '2007-06-09 18:52:19.000000', NULL, 0),
(3790648, 480747, 60862, '<td valign="top">Very touching scene, and nice title to go with it.  The snow is an excellent touch, too.</td>', 'Very touching scene, and nice title to go with it.  The snow is an excellent touch, too.', '2007-06-16 02:20:03.000000', NULL, 0),
